const items = $input.all();

return items.map((item) => {
  let data;
  const errors = [];

  // Step 1: Parse JSON string from the text field
  try {
    data = typeof item.json.text === "string"
      ? JSON.parse(item.json.text)
      : item.json;
  } catch (error) {
    return {
      json: {
        Is_Valid: false,
        Errors: ["Invalid JSON format"],
        Raw_Data: item.json.text ?? ""
      }
    };
  }

  // Step 2: Clean text values
  const clean = (value) =>
    value == null
      ? ""
      : String(value).trim().replace(/\s+/g, " ");

  const studentId = clean(data.Student_ID);
  const name = clean(data.Name);
  const email = clean(data.Email).toLowerCase();
  const phone = clean(data.Phone).replace(/[\s()-]/g, "");
  const course = clean(data.Course);
  const city = clean(data.City);
  const enrolledDate = clean(data.Enrolled_Date);

  // Step 3: Validate fields
  if (!studentId) errors.push("Missing Student_ID");
  if (!name) errors.push("Missing Name");

  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    errors.push("Invalid Email");
  }

  if (!/^[6-9]\d{9}$/.test(phone)) {
    errors.push("Invalid Phone");
  }

  if (!course) errors.push("Missing Course");
  if (!city) errors.push("Missing City");

  // Validate date strictly as YYYY-MM-DD
  let dateValid = false;

  if (/^\d{4}-\d{2}-\d{2}$/.test(enrolledDate)) {
    const date = new Date(enrolledDate + "T00:00:00Z");
    dateValid =
      !isNaN(date.getTime()) &&
      date.toISOString().slice(0, 10) === enrolledDate;
  }

  if (!dateValid) errors.push("Invalid Enrolled_Date");

  // Step 4: Normalize Fee_Paid
  let feePaid = data.Fee_Paid;

  if (typeof feePaid === "string") {
    const value = feePaid.trim().toLowerCase();

    if (["true", "yes", "1"].includes(value)) {
      feePaid = true;
    } else if (["false", "no", "0"].includes(value)) {
      feePaid = false;
    } else {
      feePaid = null;
    }
  } else if (typeof feePaid !== "boolean") {
    feePaid = null;
  }

  if (feePaid === null) {
    errors.push("Invalid Fee_Paid");
  }

  // Step 5: Return cleaned student record
  return {
    json: {
      Student_ID: studentId,
      Name: name,
      Email: email,
      Phone: phone,
      Course: course,
      Fee_Paid: feePaid,
      City: city,
      Enrolled_Date: enrolledDate,
      Is_Valid: errors.length === 0,
      Errors: errors
    }
  };
});
